            $names=$book->createElementNS($ns,'definedNames');foreach(['_DVM_MembersTemplate'=>self::MARKER,'_DVM_MembersInput'=>"'Mitglieder'!\$A\$1:\$Q\$1000"]as$name=>$value){$n=$book->createElementNS($ns,'definedName');$n->setAttribute('name',$name);$n->appendChild($book->createTextNode($value));$names->appendChild($n);}$book->documentElement->appendChild($names);
            $zip->addFromString('xl/workbook.xml',$book->saveXML());
            $rels=$xml('xl/_rels/workbook.xml.rels');$rns='http://schemas.openxmlformats.org/package/2006/relationships';foreach(['rIdInstructions'=>'sheet2.xml','rIdExample'=>'sheet3.xml']as$id=>$target){$n=$rels->createElementNS($rns,'Relationship');$n->setAttribute('Id',$id);$n->setAttribute('Type',$rel.'/worksheet');$n->setAttribute('Target','worksheets/'.$target);$rels->documentElement->appendChild($n);}$zip->addFromString('xl/_rels/workbook.xml.rels',$rels->saveXML());
