            $styles=$xml('xl/styles.xml');$fills=$styles->getElementsByTagName('fills')->item(0);$fill=$styles->createElementNS($ns,'fill');$pattern=$styles->createElementNS($ns,'patternFill');$pattern->setAttribute('patternType','solid');$fg=$styles->createElementNS($ns,'fgColor');$fg->setAttribute('rgb','FF9A3412');$pattern->appendChild($fg);$fill->appendChild($pattern);$fills->appendChild($fill);$fills->setAttribute('count',(string)$fills->childNodes->length);$xfs=$styles->getElementsByTagName('cellXfs')->item(0);$required=$xfs->childNodes->item(1)->cloneNode(true);$required->setAttribute('fillId','3');$xfs->appendChild($required);$xfs->setAttribute('count',(string)$xfs->childNodes->length);$zip->addFromString('xl/styles.xml',$styles->saveXML());
