            $validations=$sheet->createElementNS($ns,'dataValidations');$hints=self::hints();foreach(self::FIELDS as$i=>$field){$v=$sheet->createElementNS($ns,'dataValidation');$list=in_array($field,['status','family_payer'],true);$v->setAttribute('type',$list?'list':'custom');$v->setAttribute('allowBlank','1');$v->setAttribute('showInputMessage','1');$v->setAttribute('showErrorMessage',$list?'1':'0');$v->setAttribute('errorStyle','stop');$v->setAttribute('promptTitle',str_replace(' *','',self::HEADERS[$i]));$v->setAttribute('prompt',$hints[$field][2]);$v->setAttribute('sqref',chr(65+$i).'2:'.chr(65+$i).'1000');if($field==='status'){$v->setAttribute('errorTitle','Status auswählen');$v->setAttribute('error','Bitte aktiv, passiv oder ehemalig auswählen.');}$formula=$sheet->createElementNS($ns,'formula1');$formula->appendChild($sheet->createTextNode($field==='status'?'"aktiv,passiv,ehemalig"':($field==='family_payer'?'"ja,nein"':'TRUE')));$v->appendChild($formula);$validations->appendChild($v);}$validations->setAttribute('count',(string)count(self::FIELDS));$margins=$sheet->getElementsByTagName('pageMargins')->item(0);$sheet->documentElement->insertBefore($validations,$margins);$zip->addFromString('xl/worksheets/sheet1.xml',$sheet->saveXML());
            $guidance=[['Mitgliederliste ausfüllen','','',''],['Nur das Blatt „Mitglieder“ ausfüllen. Eine Person pro Zeile. Die mit * markierten Felder sind für neue Mitgliedschaften erforderlich. Die beiden anderen Blätter dienen nur der Hilfe.','','',''],['Spalte','Pflicht?','Beispiel','So trägst du es ein']];foreach(self::FIELDS as$i=>$field){[$required,$example,$hint]=$hints[$field];$guidance[]=[self::HEADERS[$i],$required,$example,$hint];}
            $guidance[]=['Danach: als .xlsx speichern → im Vereinsmanager „Excel: Import & Export“ öffnen → Datei laden → Vorschau und mögliche Dubletten prüfen → erst danach bewusst übernehmen.','','',''];$guidance[]=['Wichtig: „Beispiel“ wird nicht importiert. Bestehende Profile werden nicht überschrieben. Eine gemeinsame Familien-E-Mail führt niemanden zusammen. Keine Formeln verwenden. Bankverbindungen ausschließlich als vollständige IBAN mit Kontoinhaber eintragen; dadurch entsteht kein SEPA-Mandat.','','',''];$guidance[]=['Ein Export enthält den aktuellen oder letzten Mitgliedschaftsstand der gewählten Personen. Familienkennung, Beitragszahler und aktueller Jahresbeitrag stehen in eigenen Spalten. Bankdaten sind nur über den gesondert bestätigten Bankexport enthalten. Die ganze Mitgliedschaftshistorie bleibt im Manager. Bis zu 999 Personen pro Datei.','','',''];
