            if(!$zip->close())throw new DomainException('Excel-Datei konnte nicht abgeschlossen werden.');$opened=false;$bytes=file_get_contents($path);if(!is_string($bytes))throw new DomainException('Excel-Datei nicht lesbar.');return$bytes;
        }finally{if($opened)$zip->close();unlink($path);}
