    private static function sheet(#[\SensitiveParameter] array$rows,array$widths,bool$guide):string
    {
        $e=static fn(string$s):string=>htmlspecialchars($s,ENT_XML1|ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$last=chr(64+count($widths));$out='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><dimension ref="A1:'.$last.count($rows).'"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="'.($guide?3:1).'" topLeftCell="A'.($guide?4:2).'" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="48"/><cols>';
        foreach($widths as$i=>$width)$out.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.$width.'" customWidth="1"/>';$out.='</cols><sheetData>';foreach($rows as$i=>$row){$out.='<row r="'.($i+1).'" ht="'.($guide?($i===0?34:62):54).'" customHeight="1">';foreach($row as$j=>$value)$out.='<c r="'.chr(65+$j).($i+1).'" s="'.(($guide?in_array($i,[0,2],true):$i===0)?1:0).'" t="inlineStr"><is><t xml:space="preserve">'.$e($value).'</t></is></c>';$out.='</row>';}$out.='</sheetData>';if($guide){$merges=[1,2,count($rows)-2,count($rows)-1,count($rows)];$out.='<mergeCells count="'.count($merges).'">';foreach($merges as$row)$out.='<mergeCell ref="A'.$row.':D'.$row.'"/>';$out.='</mergeCells>';}$out.='<pageMargins left="0.3" right="0.3" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup orientation="landscape" paperSize="9" fitToWidth="1" fitToHeight="0"/></worksheet>';return$out;
    }
    public static function records(PDO$db,string$actor,string$scope,string$search):array
    {
        $registry=new Registry($db,$actor);if(!$registry->canWrite())throw new DomainException('Mitglieder-Schreibrecht erforderlich.');if(!in_array($scope,['current','members','former'],true)||!mb_check_encoding($search,'UTF-8')||mb_strlen($search)>150||preg_match('/[\x00-\x1f\x7f]/',$search))throw new DomainException('Mitgliederauswahl für Excel vollständig prüfen.');
        $filters=['list'=>$scope==='current'?'current':'members','status'=>$scope==='former'?'ehemalig':'','kind'=>'person','q'=>$search];$first=$registry->contactPage($filters,1,100);if($first['total']>self::MAX_PEOPLE)throw new DomainException('Mehr als 999 Personen. Suche eingrenzen und getrennte Excel-Dateien erstellen.');$people=$first['rows'];for($page=2;$page<=$first['pages'];++$page)$people=[...$people,...$registry->contactPage($filters,$page,100)['rows']];$records=[];
        $rates=[];try{$rates=ContributionRates::all($db,Permissions::actor($db,$actor)['club_id']);}catch(DomainException){}
        foreach($people as$c){$history=$registry->memberships($c['id']);$m=$history?end($history):null;if(!$m||$m['member_number']!==$c['member_number'])throw new DomainException('Mitgliedschaft seit der Auswahl geändert. Excel-Auswahl erneut prüfen.');$family=$registry->family($c['id']);$payer=$family!==null&&$family['payer_contact_id']===$c['id'];$fee=$family!==null&&!$payer?0:($rates[$family!==null?'family':'single']['amount_cents']??null);$records[]=['name'=>$c['name'],'number'=>$m['member_number'],'legacy'=>$c['legacy_member_number']??'','email'=>$c['email']??'','address'=>$c['address']??'','phone'=>$c['phone']??'','birthday'=>$c['birthday']??'','start'=>($m['starts_precision']??'day')==='year'?substr($m['starts_on'],0,4):$m['starts_on'],'end'=>$m['ends_on']??'','status'=>$m['status'],'iban'=>'','holder'=>'','bic'=>'','annual_fee'=>$fee===null?'':Finance::decimal($fee),'family_key'=>$family===null?'':'ID:'.$family['id'],'family_name'=>$family['name']??'','family_payer'=>$family===null?'':($payer?'ja':'nein'),'_contact_id'=>$c['id']];}
        if(!$registry->canWrite())throw new DomainException('Mitglieder-Schreibrecht erforderlich.');return$records;
    }
